// Builds public/vendor/lucide-subset.min.js from the full public/vendor/lucide.min.js.
//
// The public website only uses ~32 of lucide's 2000+ icons. Shipping the full UMD
// bundle cost ~448 KB of JavaScript on every first visit; the subset keeps the same
// `window.lucide.createIcons()` API at a fraction of the size.
//
// Run after adding a new data-lucide icon to the site:
//   node scripts/build-lucide-subset.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const SOURCE = path.join(root, 'public/vendor/lucide.min.js');
const OUTPUT = path.join(root, 'public/vendor/lucide-subset.min.js');

// Every icon name used by public/lifegen (HTML data-lucide attributes, toast() icons
// and the TYPE_META maps). Add new ones here when the site grows.
const USED = [
  'alert-triangle', 'arrow-left', 'arrow-right', 'book-open', 'calendar-check',
  'calendar-plus', 'check', 'chevron-left', 'chevron-right', 'clock', 'clock-3',
  'copy', 'heart', 'heart-handshake', 'image', 'info', 'leaf', 'lock', 'map-pin',
  'menu', 'message-circle', 'message-circle-heart', 'mouse-pointer-click',
  'pen-line', 'play', 'refresh-cw', 'send', 'share-2', 'shield-check', 'sparkles',
  'trophy', 'x',
];

const toPascalCase = (s) => {
  let out = '', cap = false;
  for (const c of s) {
    if (c === '-' || c === '_' || c <= ' ') { if (out.length) cap = true; continue; }
    out += out.length === 0 ? c.toLowerCase() : cap ? c.toUpperCase() : c;
    cap = false;
  }
  return out.charAt(0).toUpperCase() + out.slice(1);
};

// Load the full UMD build in Node; icon nodes are static arrays, no DOM needed.
const src = fs.readFileSync(SOURCE, 'utf8').replace(/\/\/# sourceMappingURL=.*/, '');
const mod = { exports: {} };
new Function('exports', 'module', src)(mod.exports, mod);
const lucide = mod.exports;

const picked = {};
for (const name of USED) {
  const key = toPascalCase(name);
  const node = lucide.icons[key];
  if (!node) throw new Error(`Icon "${name}" (lucide.icons.${key}) not found in ${SOURCE}`);
  picked[key] = node; // same PascalCase keys as the upstream lucide.icons object
}

const banner = `/**\n * lucide icon subset (${USED.length} icons) — generated by scripts/build-lucide-subset.mjs\n * from lucide v1.53.0 (ISC license). Same window.lucide.createIcons() API.\n * Do not edit by hand; rerun the script after adding icons.\n */\n`;
const code = `${banner}(function(g){'use strict';
var S={xmlns:'http://www.w3.org/2000/svg',width:24,height:24,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':2,'stroke-linecap':'round','stroke-linejoin':'round'};
function mk(n,a,c){var e=document.createElementNS(S.xmlns,n);Object.keys(a).forEach(function(k){e.setAttribute(k,String(a[k]))});(c||[]).forEach(function(x){e.appendChild(mk(x[0],x[1],x[2]))});return e}
function el(n,a){return mk('svg',Object.assign({},S,a||{}),n)}
function cls(o){if(typeof o==='string')return o.split(' ');if(!o||!o.class)return[];return typeof o.class==='string'?o.class.split(' '):Array.isArray(o.class)?o.class:[]}
function join(){var s=[];Array.prototype.forEach.call(arguments,function(v){if(v&&s.indexOf(v)<0)s.push(v)});return s.join(' ').trim()}
function attrsOf(e){return Array.from(e.attributes).reduce(function(t,c){t[c.name]=c.value;return t},{})}
function aria(o){for(var k in o)if(k.indexOf('aria-')===0||k==='role'||k==='title')return true;return false}
function pascal(s){var o='',u=false;for(var i=0;i<s.length;i++){var c=s[i];if(c==='-'||c==='_'||c<=' '){if(o.length)u=true;continue}o+=!o.length?c.toLowerCase():u?c.toUpperCase():c;u=false}return o.charAt(0).toUpperCase()+o.slice(1)}
function replace(e,o){var n=e.getAttribute(o.nameAttr);if(n==null)return;var ic=o.icons[pascal(n)];if(!ic){console.warn(''+(e.outerHTML||'')+' icon name was not found in the provided icons object.');return}var ea=attrsOf(e),h=aria(ea)?{}:{'aria-hidden':'true'},a=Object.assign({},S,{'data-lucide':n},h,o.attrs,ea),c=join('lucide','lucide-'+n,cls(ea).join(' '),cls(o.attrs).join(' '));if(c)a['class']=c;var svg=mk('svg',Object.keys(a).reduce(function(t,k){t[k]=a[k];return t},{}),[]);ic.forEach(function(ch){svg.appendChild(mk(ch[0],ch[1],ch[2]))});if(e.parentNode)e.parentNode.replaceChild(svg,e)}
var ICONS=${JSON.stringify(Object.fromEntries(Object.entries(picked)))};
function createIcons(o){o=o||{};var icons=o.icons||ICONS,nameAttr=o.nameAttr||'data-lucide',attrs=o.attrs||{},root=o.root||document;if(!Object.keys(icons).length)throw new Error('Please provide an icons object.');if(typeof root==='undefined')throw new Error('createIcons() only works in a browser environment.');Array.from(root.querySelectorAll('['+nameAttr+']')).forEach(function(e){replace(e,{nameAttr:nameAttr,icons:icons,attrs:attrs})})}
var api={createIcons:createIcons,icons:ICONS,createElement:el};
Object.keys(ICONS).forEach(function(n){api[n]=ICONS[n]});
g.lucide=api;
})(typeof globalThis!=='undefined'?globalThis:this);
`;
fs.writeFileSync(OUTPUT, code);
const kb = (n) => (n / 1024).toFixed(1) + ' KB';
console.log(`wrote ${path.relative(root, OUTPUT)}: ${USED.length} icons, ${kb(Buffer.byteLength(code))} (source ${kb(fs.statSync(SOURCE).size)})`);
